INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 1, 'Choose the correct article: ___ apple a day keeps the doctor away.', 'a', 'an', 'the', 'no article required', 'B', 'Vowel sound ''a'' in apple => use ''an''.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 2, 'Fill in the blank: She is good ___ mathematics.', 'in', 'at', 'on', 'of', 'B', '''Good at'' is the fixed collocation in English.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 3, 'The plural of ''Ox'' is:', 'Oxes', 'Oxen', 'Ox', 'Oxs', 'B', 'Ox is an irregular noun; its plural is Oxen.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 4, 'Choose the correct tense: She ___ here since 2010.', 'lives', 'is living', 'has been living', 'lived', 'C', '''Since'' with a continuous action => Present Perfect Continuous.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 5, 'Antonym of ''Benevolent'' is:', 'Kind', 'Generous', 'Malevolent', 'Helpful', 'C', 'Benevolent = kind. Malevolent = wishing evil (opposite).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 6, 'Passive voice of ''They are building a new school'':', 'A new school is being built by them.', 'A new school was built by them.', 'A new school has been built by them.', 'A new school will be built by them.', 'A', 'Present continuous passive: is/am/are + being + past participle.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 7, 'Identify the correct sentence:', 'He don''t know the answer.', 'He doesn''t knows the answer.', 'He doesn''t know the answer.', 'He not know the answer.', 'C', '3rd person singular with ''doesn''t'' => base verb form.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 8, 'Synonym of ''Diligent'':', 'Lazy', 'Hardworking', 'Careless', 'Slow', 'B', 'Diligent means hardworking and industrious.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 9, 'Choose the correct subjunctive: I wish I ___ a bird.', 'am', 'was', 'were', 'will be', 'C', 'Subjunctive mood after ''wish'' => ''were'' for all persons.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'English', 'English Grammar & Vocabulary', 10, 'The idiom ''Bite the bullet'' means:', 'To eat something hard', 'To endure pain bravely', 'To shoot someone', 'To be very hungry', 'B', 'Bite the bullet = accept a painful/difficult situation with courage.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 11, '''चांदी'' शब्द में कौन-सी संज्ञा है?', 'द्रव्यवाचक संज्ञा', 'जातिवाचक संज्ञा', 'भाववाचक संज्ञा', 'व्यक्तिवाचक संज्ञा', 'A', 'धातु/पदार्थ का नाम => द्रव्यवाचक संज्ञा। चांदी एक धातु है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 12, 'निम्नलिखित में से कौन-सा ''तत्सम'' शब्द है?', 'घर', 'स्नेह', 'आंसू', 'आम', 'B', 'स्नेह संस्कृत का मूल (तत्सम) शब्द है।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 13, '''जिसकी यह पुस्तक है, उसे लौटा दो'' - इसमें कौन-सा सर्वनाम है?', 'निश्चयवाचक', 'संबंधवाचक', 'पुरुषवाचक', 'प्रश्नवाचक', 'B', 'जिस-उस = संबंधवाचक सर्वनाम।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 14, 'निम्नलिखित में शुद्ध वर्तनी वाला शब्द कौन-सा है?', 'क्षत्रिय', 'क्षत्री', 'क्षत्रीय', 'छत्रिय', 'A', 'सही वर्तनी: क्षत्रिय।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 15, '''खारिज'' किस भाषा का शब्द है?', 'अरबी', 'फारसी', 'तुर्की', 'पुर्तगाली', 'A', 'खारिज अरबी मूल का शब्द है।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 16, 'रचना के आधार पर जिन शब्दों के खंड सार्थक न हों, उन्हें कहते हैं:', 'रूढ़', 'यौगिक', 'योगरूढ़', 'मिश्रित', 'A', 'रूढ़ शब्द के टुकड़े सार्थक नहीं होते। जैसे: कमल।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 17, '''जसोदा हरि पालने झुलावे'' - इस काव्य में कौन-सा रस है?', 'श्रृंगार', 'वीर', 'वात्सल्य', 'करुण', 'C', 'माँ यशोदा का कृष्ण के प्रति प्रेम = वात्सल्य रस।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 18, 'हिंदी भाषा के उद्भव का काल माना जाता है:', '500 ई. पू.', '500 ई.', '1000 ई.', '1200 ई.', 'C', 'हिंदी का उद्भव लगभग 1000 ई. माना जाता है।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 19, '''उसका भविष्य उज्ज्वल है'' - रेखांकित शब्द की शुद्ध वर्तनी:', 'उज्जवल', 'उजवल', 'उज्ज्वल', 'उज्वल', 'C', 'सही वर्तनी: उज्ज्वल।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 20, 'जिन शब्दों पर लिंग, वचन, कारक का प्रभाव न पड़े, वे कहलाते हैं:', 'व्यय', 'विकारी', 'अविकारी', 'सर्वनाम', 'C', 'अविकारी (अव्यय) शब्द लिंग-वचन से अप्रभावित रहते हैं।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 21, '''कुरुक्षेत्र'' के लेखक कौन हैं?', 'हरिऔध', 'श्रीधर पाठक', 'रामधारी सिंह दिनकर', 'मैथिलीशरण गुप्त', 'C', 'कुरुक्षेत्र - रामधारी सिंह ''दिनकर'' की प्रसिद्ध रचना।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 22, 'निम्नलिखित में विदेशी शब्द कौन-सा है?', 'बाघ', 'परीक्षा', 'चाय', 'घर', 'C', 'चाय - चीनी भाषा से आया शब्द है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 23, 'अशुद्ध-शुद्ध का कौन-सा युग्म गलत है?', 'कोमलांगिनी - कोमलांगी', 'सुश्रूषा - सुश्रुषा', 'माहात्म्य - महात्म्य', 'सब सही', 'B', 'सुश्रूषा ही सही है; ''सुश्रुषा'' गलत है। अत: (B) गलत युग्म।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 24, 'निम्नलिखित में एकवचन शब्द कौन-सा है?', 'हस्ताक्षर', 'छाया', 'आंसू', 'पत्तियां', 'B', 'छाया एकवचन है; बहुवचन: छाएं।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 25, '''सेवक नदी से गागर भरता है'' - इसमें कौन-सी क्रिया है?', 'अकर्मक', 'सकर्मक', 'प्रेरणार्थक', 'संयुक्त', 'B', 'गागर = कर्म है; अत: यह सकर्मक क्रिया है।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 26, 'भारतीय काव्यशास्त्र में क्षमाशील, गम्भीर, स्वाभिमानी नायक:', 'धीरललित', 'धीरोदात्त', 'धीर प्रशांत', 'धीरोद्धत', 'B', 'धीरोदात्त = क्षमाशील + गम्भीर + स्थिरचित्त + स्वाभिमानी।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 27, 'निम्नलिखित में देशज शब्द कौन-सा है?', 'आवारा', 'भौंरा', 'परवल', 'कमरा', 'B', 'भौंरा देशज (देशी मूल) शब्द है।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 28, 'हिंदी शब्दकोश में ''क्ष'' किस वर्ण के बाद आता है?', 'त्र के बाद', 'ज्ञ के बाद', 'क के बाद', 'ष के बाद', 'B', 'शब्दकोश क्रम: ...ज्ञ => क्ष => त्र', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 29, 'विशेषण का प्रमुख भेद कौन-सा नहीं है?', 'असार्वनामिक विशेषण', 'गुणवाचक विशेषण', 'परिमाणवाचक विशेषण', 'सार्वनामिक विशेषण', 'A', '''असार्वनामिक विशेषण'' व्याकरण में मान्य प्रमुख भेद नहीं है।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 30, '''उसका भविष्य उज्ज्वल है'' में ''उसका'' कौन-सा सर्वनाम है?', 'निश्चयवाचक', 'संबंधवाचक', 'पुरुषवाचक', 'प्रश्नवाचक', 'C', 'उसका = तृतीय पुरुष => पुरुषवाचक सर्वनाम।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 2, 'GS', 'Mathematics & Reasoning', 1, 'A rectangular hall has perimeter 250 m. Cost of painting 4 walls at Rs.10/m2 is Rs.15000. Height of hall:', '5 m', '6 m', '7 m', '8 m', 'B', '2(l+b)=250 => l+b=125. Wall area=perimeter x h. 125 x h x 10=15000 => h=12. Recalc: 15000/10=1500; 1500/250=6 m.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 2, 'GS', 'Mathematics & Reasoning', 2, 'Which statement is NOT true?', 'Every natural number is a whole number.', 'Every integer is a whole number.', 'Every natural number is an integer.', 'Zero is a whole number.', 'B', 'Integers include negatives; whole numbers do not. So ''every integer is whole number'' is FALSE.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 2, 'GS', 'Mathematics & Reasoning', 3, 'Average of 7 consecutive numbers is 20. The largest number is:', '20', '23', '21', '22', 'B', 'Middle (4th) = average = 20. Numbers: 17,18,19,20,21,22,23. Largest=23.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 2, 'GS', 'Mathematics & Reasoning', 4, 'Equation ax2+bx+c=0 has two distinct real roots if:', 'b2-4ac < 0', 'b2-4ac > 0', 'b2-4ac = 0', 'b2-4ac >= 0', 'B', 'Discriminant D=b2-4ac. D>0 => two distinct real roots.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 2, 'GS', 'Mathematics & Reasoning', 5, 'Mohan finishes work in 25 days, Sohan in 20 days. Together 5 days, then Mohan leaves. Days for Sohan alone:', '11 days', '14 days', '15 days', '20 days', 'A', '5 days together: 5(1/25+1/20)=5x9/100=9/20. Remaining=11/20. Sohan: (11/20)/(1/20)=11 days.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 2, 'GS', 'Science (Physics/Chem/Bio)', 6, 'Myopia - a person cannot see:', 'Distant objects clearly', 'Nearby objects clearly', 'Both clearly', 'Coloured objects', 'A', 'Myopia = nearsightedness => cannot see DISTANT objects clearly.', 'E');
