INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'DBMS & SQL', 47, 'Degree=4, Cardinality=3. Add 3 attributes and 4 tuples. New cardinality and degree:', '7 and 6', '7 and 7', '8 and 6', '6 and 7', 'B', 'New degree=4+3=7 attributes. New cardinality=3+4=7 tuples.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'DBMS & SQL', 48, 'SQL command to permanently remove a table from database:', 'DELETE', 'ERASE', 'REMOVE', 'DROP', 'D', 'DROP TABLE removes table and its structure. DELETE only removes rows.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'DBMS & SQL', 49, 'ACID property ensuring transaction is all-or-nothing:', 'Consistency', 'Isolation', 'Durability', 'Atomicity', 'D', 'Atomicity = either all operations of transaction complete or none do.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'DBMS & SQL', 50, 'SQL command to give user access permissions:', 'ALLOW', 'PERMIT', 'GRANT', 'AUTHORIZE', 'C', 'GRANT is a DCL command that gives specified privileges to a user.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 51, 'End-to-end connectivity from host to host is provided by:', 'Network Layer', 'Transport Layer', 'Session Layer', 'Application Layer', 'B', 'Transport Layer (Layer 4 of OSI) provides end-to-end host-to-host communication.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 52, 'Topology using single connection (backbone) for all devices:', 'Star', 'Bus', 'Ring', 'Mesh', 'B', 'Bus topology: all devices share a single backbone cable.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 53, 'Used to connect devices in a very close geographic area:', 'WAN', 'MAN', 'LAN', 'PAN', 'C', 'LAN (Local Area Network) covers small areas like a floor of a building.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 54, 'Size of IP address in IPv4:', '8 bits', '16 bits', '32 bits', '64 bits', 'C', 'IPv4 address = 32 bits (4 octets), e.g., 192.168.1.1', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 55, 'Size of MAC address:', '32 bits', '16 bits', '64 bits', '48 bits', 'D', 'MAC address = 48 bits (6 bytes), written as AA:BB:CC:DD:EE:FF.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 56, 'Gaining illegal entry to computer files through remote terminals:', 'Decoding', 'Hacking', 'Cracking', 'Phishing', 'B', 'Hacking = unauthorized access to computer systems.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 57, 'Essential ability of a computer virus:', 'Damage data', 'Damage programs', 'Clone itself', 'Delete files', 'C', 'A virus must self-replicate (clone itself) to spread. That is its defining property.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 58, 'Layer handling logical addressing (IP) and routing:', 'Data Link Layer', 'Transport Layer', 'Network Layer', 'Session Layer', 'C', 'Network Layer (Layer 3) handles IP addressing and packet routing.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 59, 'Protocol that automatically assigns IP addresses:', 'DNS', 'FTP', 'DHCP', 'HTTP', 'C', 'DHCP (Dynamic Host Configuration Protocol) auto-assigns IP to devices.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Networks', 60, 'Which measures lost/garbled messages as fraction of total sent?', 'Residual error rate', 'Transfer failure probability', 'Connection release failure probability', 'Bit error rate', 'A', 'Residual error rate measures remaining errors after error control in a sampling period.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 61, 'Three main components of a digital computer system:', 'Memory, I/O, DMA', 'ALU, CPU, Memory', 'Memory, CPU, I/O', 'CU, ALU, I/O', 'C', 'Digital computer: CPU (processes) + Memory (stores) + I/O (communicates).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 62, 'Last memory location FFFF (hex) => memory size:', '16K', '32K', '64K', '128K', 'C', 'FFFF hex = 65535. Total=65536 locations = 2^16 = 64KB.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 63, 'Minimum cost per bit storage is in:', 'Cache', 'Register', 'Magnetic Tape', 'RAM', 'C', 'Magnetic tape has highest capacity and lowest cost per bit (slowest access).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 64, 'Register containing address of NEXT instruction:', 'Instruction Register', 'Accumulator', 'Program Counter', 'Memory Address Register', 'C', 'Program Counter (PC) always points to the next instruction to execute.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 65, 'Register holding the instruction CURRENTLY being executed:', 'Accumulator', 'Program Counter', 'Memory Buffer Register', 'Instruction Register', 'D', 'Instruction Register (IR) holds the instruction currently being decoded/executed.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 66, 'Register holding address of memory location for data transfer:', 'Index Register', 'Memory Buffer Register', 'Memory Address Register', 'Stack Pointer', 'C', 'MAR (Memory Address Register) holds the address being accessed.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 67, 'Storage device compensating speed difference between components:', 'Main Memory', 'Auxiliary Memory', 'Cache', 'Buffer', 'D', 'Buffer temporarily holds data to compensate speed difference between devices.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Computer Architecture', 68, 'Memory where any location is accessed in the same fixed time:', 'Sequential Access Memory', 'Secondary Memory', 'Random Access Memory', 'Virtual Memory', 'C', 'RAM = Random Access Memory; access time is same for any location.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 69, 'Convert (1010) base 2 to decimal:', '8', '10', '12', '14', 'B', '1x2^3 + 0x2^2 + 1x2^1 + 0x2^0 = 8+0+2+0 = 10.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 70, '8-bit 2''s complement representation range:', '-128 to +128', '-127 to +127', '-128 to +127', '-127 to +128', 'C', '8-bit 2''s complement: -2^7 to 2^7-1 = -128 to +127.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 71, 'Which 4-bit number equals its own 2''s complement?', '1010', '0101', '1000', '0000', 'C', '1000: flip=0111, add 1=1000. Same number! (Also 0000 works).', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 72, 'Convert (FF) base 16 to decimal:', '225', '240', '255', '250', 'C', 'F=15. FF = 15x16 + 15x1 = 240+15 = 255.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 73, 'Boolean expression x + x''y equals:', 'x+y', 'x*y', 'x', 'y', 'A', 'x+x''y = x+y (Boolean theorem: consensus/absorption extension).', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 74, 'Boolean expression x + xy equals:', 'x', 'y', 'x+y', 'xy', 'A', 'x+xy = x(1+y) = x*1 = x (Absorption law).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 75, 'Boolean expression x(x+y) equals:', 'x', 'y', 'xy', 'x+y', 'A', 'x(x+y) = xx+xy = x+xy = x(1+y) = x (Absorption law).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 76, 'Maximum Boolean functions for 2 variables (2-valued Boolean algebra):', '8', '12', '16', '32', 'C', '2 vars => 2^2=4 input rows => 2^4=16 distinct Boolean functions possible.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 77, 'Universal gate(s) in logic design:', 'AND only', 'OR only', 'NAND only', 'Both NAND and NOR', 'D', 'NAND and NOR are both universal gates; any Boolean function can be built from either.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Number Systems & Boolean Algebra', 78, 'Minimum NAND gates to implement f = x''y + xy'' (XOR):', '3', '4', '5', '6', 'B', 'XOR using NAND requires exactly 4 NAND gates.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Cyber Security', 79, 'Copying software without author''s permission is called:', 'Larceny', 'Software Piracy', 'Hacking', 'Plagiarism', 'B', 'Software Piracy = unauthorized copying/distribution of copyrighted software.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (1, 3, 'CS', 'Cyber Security', 80, 'Hard disk becomes inaccessible when virus corrupts:', 'Partition Table', 'File Allocation Table', 'Root Directory', 'Boot Sector', 'A', 'Corrupted partition table prevents OS from locating any partition on disk.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 1, 'Choose the correct preposition: He is afraid ___ dogs.', 'of', 'from', 'with', 'for', 'A', '''Afraid of'' is the correct fixed preposition.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 2, 'Select the correctly spelt word:', 'Recieve', 'Receive', 'Receve', 'Receeve', 'B', 'Receive is the correct spelling (an exception to the ''i before e'' rule).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 3, 'Fill in the blank: Neither the teacher nor the students ___ present.', 'was', 'is', 'were', 'has', 'C', 'With ''neither...nor'', the verb agrees with the nearer subject (students, plural) => were.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 4, 'Synonym of ''Candid'':', 'Secretive', 'Frank', 'Rude', 'Shy', 'B', 'Candid means open and honest (frank) in expression.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 5, 'Antonym of ''Ancient'':', 'Old', 'Modern', 'Historic', 'Aged', 'B', 'Ancient (very old) is opposite of Modern (recent/current).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 6, 'Change to indirect speech: He said, "I am busy today."', 'He said that he was busy that day.', 'He said that he is busy today.', 'He said that he was busy today.', 'He tells that he was busy that day.', 'A', 'Present tense and ''today'' shift to past tense and ''that day'' in reported speech.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 7, 'The idiom ''A blessing in disguise'' means:', 'An obvious advantage', 'Something good that initially seemed bad', 'A curse', 'A hidden threat', 'B', 'It refers to a good thing that appeared bad or unfortunate at first.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 8, 'Identify the correctly punctuated sentence:', 'Wheres my book', 'Where''s my book?', 'Wheres'' my book?', 'Where''s my book', 'B', 'Contraction ''Where''s'' needs an apostrophe, and a question needs a question mark.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 9, 'Choose the correct passive form: ''Someone has stolen my bicycle.''', 'My bicycle is stolen.', 'My bicycle was stolen.', 'My bicycle has been stolen.', 'My bicycle had been stolen.', 'C', 'Present perfect active converts to present perfect passive: has been + past participle.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'English', 'English Grammar & Vocabulary', 10, 'The phrase ''Once in a blue moon'' means:', 'Every month', 'Very rarely', 'At midnight', 'Frequently', 'B', 'It describes something that happens very rarely.', 'E');
