INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 17, '''जो कठिनाई से प्राप्त हो'' के लिए एक शब्द है:', 'सुलभ', 'दुर्लभ', 'सुगम', 'अगम्य', 'B', 'दुर्लभ = जो कठिनाई से प्राप्त हो।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 18, 'हिंदी वर्णमाला में स्वरों की संख्या सामान्यतः मानी जाती है:', '10', '11', '13', '33', 'B', 'हिंदी में सामान्यतः 11 स्वर माने जाते हैं।', 'M');
