INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 21, '''लौकिक'' का विलोम शब्द है:', 'सांसारिक', 'अलौकिक', 'भौतिक', 'प्राकृतिक', 'B', 'लौकिक (सांसारिक) का विलोम अलौकिक (दिव्य) है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 22, 'कारक के कितने भेद माने गए हैं?', '6', '7', '8', '9', 'C', 'हिंदी व्याकरण में कारक के 8 भेद होते हैं।', 'M');
