INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 26, 'निम्न में विशेषण कौन-सा है?', 'दौड़ना', 'सुंदर', 'तेजी से', 'किताब', 'B', '''सुंदर'' संज्ञा की विशेषता बताता है, अतः विशेषण है।', 'E');
