INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 2, 'GS', 'Math & Reasoning', 1, 'A sum of Rs.4800 becomes Rs.6000 in 5 years at simple interest. Find the rate %.', '4%', '5%', '6%', '7%', 'B', 'SI=1200, P=4800, T=5. R=(SI*100)/(P*T)=(1200*100)/(4800*5)=5%.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 2, 'GS', 'Math & Reasoning', 2, 'Find the next number: 2, 6, 12, 20, 30, ?', '36', '40', '42', '44', 'C', 'Differences are 4,6,8,10,12 (increasing by 2). 30+12=42.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 2, 'GS', 'Math & Reasoning', 3, 'If 20% of a number is 50, the number is:', '200', '250', '300', '150', 'B', 'Number = 50/0.20 = 250.', 'E');
