INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'System Software', 12, 'Which is an example of an open-source operating system?', 'Windows', 'macOS', 'Linux', 'iOS', 'C', 'Linux is open-source; its source code is freely available and modifiable.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 13, 'Which data structure is used in recursion (implicitly)?', 'Queue', 'Stack', 'Tree', 'Graph', 'B', 'Function calls are managed using a call stack (LIFO) during recursion.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 14, 'Time complexity of binary search on a sorted array of n elements:', 'O(n)', 'O(n^2)', 'O(log n)', 'O(1)', 'C', 'Binary search halves the search space each step, giving O(log n).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 15, 'A linked list where the last node points to the first node is called:', 'Singly linked list', 'Doubly linked list', 'Circular linked list', 'Linear linked list', 'C', 'Circular linked list: the last node''s next pointer references the head node.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 16, 'Which sorting algorithm has the best average time complexity?', 'Bubble Sort', 'Selection Sort', 'Quick Sort', 'Insertion Sort', 'C', 'Quick Sort has average time complexity O(n log n), better than the O(n^2) others.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 17, 'In a Binary Search Tree, the left child is always:', 'Greater than parent', 'Less than parent', 'Equal to parent', 'Unrelated to parent', 'B', 'BST property: left subtree values < node value < right subtree values.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 18, 'Which traversal of a Binary Tree visits Left-Root-Right?', 'Preorder', 'Inorder', 'Postorder', 'Level order', 'B', 'Inorder traversal: Left subtree, Root, Right subtree.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 19, 'The worst-case time complexity of Bubble Sort is:', 'O(n)', 'O(n log n)', 'O(n^2)', 'O(log n)', 'C', 'Bubble Sort compares every pair in nested loops, giving O(n^2) worst case.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Data Structures', 20, 'A graph with no cycles and connected is called a:', 'Tree', 'Forest', 'Cycle graph', 'Complete graph', 'A', 'A connected acyclic graph is by definition a Tree.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 21, 'Which header file is required for printf() in C?', '<conio.h>', '<stdio.h>', '<stdlib.h>', '<string.h>', 'B', '<stdio.h> (Standard Input Output) provides printf() and scanf().', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 22, 'What is the output of: printf("%d", 5/2);', '2.5', '2', '3', '2.0', 'B', 'Integer division in C truncates the decimal part: 5/2 = 2.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 23, 'Which operator is used to access a structure member via a pointer?', '.', '->', '::', '&', 'B', 'The arrow operator (->) accesses structure members through a pointer.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 24, 'What does the ''static'' keyword do to a local variable in C?', 'Deletes it after function ends', 'Preserves its value between function calls', 'Makes it global', 'Makes it constant', 'B', 'A static local variable retains its value across multiple function calls.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 25, 'Which loop guarantees at least one execution of the body?', 'for', 'while', 'do-while', 'if', 'C', 'do-while checks the condition after executing the loop body once.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 26, 'The default return type of a function in C (if not specified) is:', 'void', 'int', 'float', 'char', 'B', 'In traditional C, an unspecified return type defaults to int.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 27, 'Which of these correctly declares a pointer to an integer?', 'int ptr;', 'int *ptr;', 'ptr int;', '*int ptr;', 'B', '''int *ptr;'' declares ptr as a pointer to an int.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 28, 'What is the size of a ''char'' data type in C (typical systems)?', '1 byte', '2 bytes', '4 bytes', '8 bytes', 'A', 'A char occupies 1 byte (8 bits) on virtually all systems.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 29, 'Which function is used to dynamically allocate memory in C?', 'alloc()', 'malloc()', 'new()', 'create()', 'B', 'malloc() (memory allocation) dynamically allocates memory on the heap.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C Programming', 30, 'What does ''&&'' represent in C?', 'Bitwise AND', 'Logical AND', 'Logical OR', 'Bitwise OR', 'B', '''&&'' is the logical AND operator, used in conditional expressions.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 31, 'Which OOP concept restricts direct access to data members?', 'Inheritance', 'Polymorphism', 'Encapsulation', 'Abstraction', 'C', 'Encapsulation bundles data with methods and restricts direct external access.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 32, 'Which type of inheritance involves a class derived from two base classes?', 'Single', 'Multiple', 'Multilevel', 'Hierarchical', 'B', 'Multiple inheritance: one derived class inherits from more than one base class.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 33, 'A pure virtual function is declared using:', '= 0', '= NULL', 'virtual only', 'abstract keyword', 'A', 'A pure virtual function is declared as: virtual void func() = 0;', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 34, 'Which concept allows a derived class object to be treated as a base class object?', 'Overloading', 'Overriding', 'Upcasting (Polymorphism)', 'Encapsulation', 'C', 'Upcasting, a form of polymorphism, allows a derived object to be referenced as its base type.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 35, 'What is the default access specifier for inheritance in C++ class (class Derived : Base)?', 'public', 'protected', 'private', 'none', 'C', 'If not specified, class inheritance defaults to ''private'' in C++.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 36, '''this'' pointer in C++ refers to:', 'The base class', 'The current object', 'A static member', 'A global variable', 'B', 'The ''this'' pointer holds the address of the current (calling) object.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 37, 'Which operator can be overloaded in C++?', 'sizeof only', 'Almost all operators except a few (like ::, ., ?:)', 'No operators', 'Only arithmetic operators', 'B', 'C++ allows overloading most operators, except a small set like ::, ., .*, ?:', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'C++ & OOP', 38, 'Function overriding requires:', 'Same function name, same signature, in base and derived class', 'Different function names', 'Different return types only', 'Static binding', 'A', 'Overriding requires the derived class to redefine a base class function with the same name/signature.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 39, 'A table in a relational database is also known as:', 'Tuple', 'Relation', 'Attribute', 'Domain', 'B', 'A table is formally called a ''relation'' in relational database theory.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 40, 'Which SQL clause is used to filter groups after GROUP BY?', 'WHERE', 'HAVING', 'FILTER', 'ORDER BY', 'B', 'HAVING filters aggregated groups; WHERE filters rows before grouping.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 41, 'Which key uniquely identifies each row and cannot be NULL?', 'Foreign Key', 'Candidate Key', 'Primary Key', 'Super Key', 'C', 'Primary Key uniquely identifies each row and must not contain NULL values.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 42, 'A relation is in 1NF if:', 'It has a primary key', 'All attributes contain atomic (indivisible) values', 'It has no foreign key', 'It is fully normalized', 'B', 'First Normal Form (1NF) requires all attribute values to be atomic (no repeating groups).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 43, 'Which SQL command is used to remove all rows from a table but keep its structure?', 'DROP', 'DELETE', 'TRUNCATE', 'REMOVE', 'C', 'TRUNCATE removes all rows quickly while keeping the table structure intact.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 44, 'A JOIN that returns only matching rows from both tables is called:', 'LEFT JOIN', 'RIGHT JOIN', 'INNER JOIN', 'FULL OUTER JOIN', 'C', 'INNER JOIN returns only rows with matching values in both joined tables.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 45, 'Which normal form removes transitive dependency?', '1NF', '2NF', '3NF', 'BCNF', 'C', 'Third Normal Form (3NF) removes transitive dependencies on the primary key.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 46, 'The ACID property ensuring database consistency remains valid before and after a transaction:', 'Atomicity', 'Consistency', 'Isolation', 'Durability', 'B', 'Consistency ensures the database moves from one valid state to another.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 47, 'Which SQL keyword removes duplicate rows from a result set?', 'UNIQUE', 'DISTINCT', 'REMOVE DUPLICATE', 'ONLY', 'B', 'SELECT DISTINCT eliminates duplicate rows from query results.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 48, 'A schema that describes the overall database design (conceptual level) is:', 'Physical schema', 'Logical schema', 'External schema', 'View schema', 'B', 'The logical/conceptual schema describes the overall structure for the whole database.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 49, 'Which SQL constraint ensures a column''s values must be unique across the table?', 'CHECK', 'UNIQUE', 'DEFAULT', 'NOT NULL', 'B', 'The UNIQUE constraint ensures all values in a column are distinct.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'DBMS & SQL', 50, 'In an E-R diagram, a diamond shape represents:', 'Entity', 'Attribute', 'Relationship', 'Key', 'C', 'In Entity-Relationship diagrams, a diamond denotes a relationship between entities.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 51, 'How many layers does the OSI model have?', '5', '6', '7', '8', 'C', 'The OSI (Open Systems Interconnection) model has 7 layers.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 52, 'Which protocol is used to send email?', 'FTP', 'SMTP', 'HTTP', 'POP3', 'B', 'SMTP (Simple Mail Transfer Protocol) is used to send email.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 53, 'Which device operates at the Data Link Layer and uses MAC addresses?', 'Router', 'Switch', 'Hub', 'Repeater', 'B', 'A Switch forwards frames based on MAC addresses at Layer 2.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 54, 'HTTPS uses which port by default?', '80', '21', '443', '25', 'C', 'HTTPS (secure HTTP) uses port 443 by default.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 55, 'Which topology connects every node to a central hub/switch?', 'Bus', 'Ring', 'Star', 'Mesh', 'C', 'In Star topology, all nodes connect individually to a central hub or switch.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 56, 'What does DNS stand for?', 'Domain Name System', 'Data Network Service', 'Domain Network Server', 'Digital Name System', 'A', 'DNS translates human-readable domain names into IP addresses.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 57, 'A firewall is primarily used to:', 'Increase internet speed', 'Filter/block unauthorized network traffic', 'Store data', 'Compress files', 'B', 'A firewall monitors and filters incoming/outgoing network traffic based on security rules.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 58, 'Which is a connection-oriented transport layer protocol?', 'UDP', 'TCP', 'IP', 'ICMP', 'B', 'TCP (Transmission Control Protocol) establishes a connection before data transfer.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 59, 'IPv6 address size is:', '32 bits', '64 bits', '128 bits', '256 bits', 'C', 'IPv6 uses 128-bit addresses, vastly larger than IPv4''s 32-bit space.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Networks', 60, 'Which attack floods a server with excessive traffic to make it unavailable?', 'Phishing', 'DoS/DDoS attack', 'Spoofing', 'SQL Injection', 'B', 'A Denial of Service (DoS/DDoS) attack overwhelms a server with traffic, denying legitimate access.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 61, 'Which unit performs arithmetic and logical operations?', 'Control Unit', 'ALU', 'Memory Unit', 'I/O Unit', 'B', 'The Arithmetic Logic Unit (ALU) performs all arithmetic and logical operations.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 62, 'Which register holds the result of the last ALU operation temporarily?', 'Program Counter', 'Accumulator', 'Instruction Register', 'Stack Pointer', 'B', 'The Accumulator register holds intermediate arithmetic/logic results.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 63, 'Pipelining in CPU design improves:', 'Memory capacity', 'Instruction throughput', 'Storage cost', 'Power consumption only', 'B', 'Pipelining overlaps instruction execution stages, improving overall throughput.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 64, 'Cache memory is placed between:', 'CPU and RAM', 'RAM and Hard Disk', 'CPU and Hard Disk', 'Keyboard and CPU', 'A', 'Cache sits between CPU and main memory (RAM) to speed up data access.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 65, 'Which addressing mode uses the operand''s value directly in the instruction?', 'Direct addressing', 'Immediate addressing', 'Indirect addressing', 'Register addressing', 'B', 'Immediate addressing embeds the actual constant value within the instruction itself.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 66, 'RISC architecture is characterized by:', 'Complex, many instructions', 'Simple, fewer instructions executed quickly', 'No pipelining', 'Only used in mainframes', 'B', 'RISC (Reduced Instruction Set Computer) uses a small set of simple, fast instructions.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 67, 'Which memory type is fastest but most expensive per bit?', 'Registers', 'Cache', 'RAM', 'Hard Disk', 'A', 'CPU Registers are the fastest storage, directly inside the processor, but very limited and costly.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Computer Architecture', 68, 'Von Neumann architecture uses:', 'Separate memory for data and instructions', 'A single shared memory for data and instructions', 'No memory at all', 'Only cache memory', 'B', 'Von Neumann architecture stores both program instructions and data in the same memory.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 69, 'Convert binary 1101 to decimal:', '11', '12', '13', '14', 'C', '1x8+1x4+0x2+1x1 = 8+4+0+1 = 13.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 70, 'Convert decimal 25 to binary:', '11001', '11010', '10101', '11100', 'A', '25 = 16+8+1 = 11001 in binary.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 71, 'In Boolean algebra, A + A'' equals:', '0', '1', 'A', 'A''', 'B', 'A OR NOT-A is always true (1), by the complement law.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 72, 'In Boolean algebra, A . A'' equals:', '0', '1', 'A', 'A''', 'A', 'A AND NOT-A is always false (0), by the complement law.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 73, 'The output of an XOR gate is 1 when inputs are:', 'Both same (00 or 11)', 'Different (01 or 10)', 'Both 0', 'Both 1', 'B', 'XOR (exclusive OR) outputs 1 only when the two inputs differ.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 74, 'Which gate gives output 1 only when all inputs are 1?', 'OR', 'NOR', 'AND', 'NAND', 'C', 'AND gate outputs 1 only when every input is 1.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 75, 'Hexadecimal number system has a base of:', '2', '8', '10', '16', 'D', 'Hexadecimal uses 16 symbols (0-9, A-F), hence base 16.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 76, 'Convert octal 17 to decimal:', '13', '15', '17', '19', 'B', '1x8 + 7x1 = 8+7 = 15.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 77, 'De Morgan''s theorem states that (A.B)'' equals:', 'A'' . B''', 'A'' + B''', 'A + B', 'A . B', 'B', 'De Morgan''s law: (A.B)'' = A'' + B'' (NOT of AND = OR of NOTs).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Number Systems & Boolean Algebra', 78, '1''s complement of binary 1010 is:', '0101', '1011', '0100', '1111', 'A', '1''s complement flips every bit: 1010 -> 0101.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Cyber Security', 79, 'A program that disguises itself as legitimate software but performs malicious actions is called:', 'Worm', 'Trojan Horse', 'Adware', 'Firewall', 'B', 'A Trojan Horse appears legitimate/useful but secretly performs harmful actions.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (2, 3, 'CS', 'Cyber Security', 80, 'The practice of sending fraudulent emails to steal sensitive data is called:', 'Hacking', 'Phishing', 'Spamming', 'Encryption', 'B', 'Phishing uses deceptive emails/messages to trick users into revealing sensitive information.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 1, 'Choose the correct form: She ___ to the market every Sunday.', 'go', 'goes', 'going', 'gone', 'B', 'Simple present tense with third person singular subject ''She'' needs ''goes''.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 2, 'Select the correctly spelt word:', 'Occassion', 'Occasion', 'Ocassion', 'Occasion''s', 'B', 'Occasion is the correct spelling (single ''s'', double ''c'').', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 3, 'Fill in the blank: I have been waiting ___ two hours.', 'since', 'for', 'from', 'at', 'B', '''For'' is used with a duration of time; ''since'' is used with a point in time.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 4, 'Synonym of ''Meticulous'':', 'Careless', 'Careful', 'Lazy', 'Quick', 'B', 'Meticulous means showing great attention to detail; i.e., very careful.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 5, 'Antonym of ''Generous'':', 'Kind', 'Stingy', 'Wealthy', 'Helpful', 'B', 'Generous (giving freely) is opposite of Stingy (unwilling to give).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 6, 'Change to passive voice: ''They are painting the wall.''', 'The wall is painted by them.', 'The wall is being painted by them.', 'The wall was painted by them.', 'The wall has been painted by them.', 'B', 'Present continuous active converts to present continuous passive: is/am/are + being + past participle.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 7, 'The idiom ''To beat around the bush'' means:', 'To attack directly', 'To avoid the main topic', 'To win a game', 'To garden', 'B', 'It means avoiding the main point of a discussion, speaking indirectly.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 8, 'Identify the correctly punctuated sentence:', 'Its a beautiful day.', 'It''s a beautiful day.', 'Its'' a beautiful day.', 'It is a beautiful day', 'B', '''It''s'' (contraction of ''it is'') requires an apostrophe.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 9, 'Choose the correct comparative form: This book is ___ than that one.', 'interesting', 'more interesting', 'most interesting', 'interestinger', 'B', 'For multi-syllable adjectives, comparative form uses ''more'' + adjective.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'English', 'English Grammar & Vocabulary', 10, 'The phrase ''To hit the nail on the head'' means:', 'To make a mistake', 'To say exactly the right thing', 'To build furniture', 'To fail completely', 'B', 'It means to describe or identify a situation exactly and accurately.', 'M');
