INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 17, '''जो देखा न जा सके'' के लिए एक शब्द है:', 'अदृश्य', 'दृश्य', 'अगोचर', 'सुदृश्य', 'A', 'अदृश्य = जो देखा न जा सके।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 18, 'हिंदी वर्णमाला में व्यंजनों की संख्या मानी जाती है:', '33', '35', '36', '39', 'A', 'हिंदी में सामान्यतः 33 मूल व्यंजन माने जाते हैं।', 'M');
