INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 22, 'कारक चिह्न ''को'' किस कारक में प्रयुक्त होता है?', 'कर्ता कारक', 'कर्म कारक', 'करण कारक', 'संप्रदान कारक', 'B', '''को'' विभक्ति चिह्न मुख्यतः कर्म कारक में प्रयुक्त होता है।', 'M');
