INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 2, 'GS', 'Math & Reasoning', 1, 'A sum of Rs.8000 is lent at 10% p.a. compound interest for 2 years. The compound interest is:', 'Rs.1600', 'Rs.1680', 'Rs.1700', 'Rs.1800', 'B', 'CI = P[(1+r/100)^n - 1] = 8000[(1.1)^2-1] = 8000(0.21) = 1680.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 2, 'GS', 'Math & Reasoning', 2, 'Find the missing number: 5, 11, 23, 47, ?', '93', '94', '95', '96', 'A', 'Each term = previous term x2 + 1. 47x2+1=95.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 2, 'GS', 'Math & Reasoning', 3, 'If a:b = 2:3 and b:c = 4:5, then a:b:c is:', '8:12:15', '2:3:5', '8:9:15', '4:6:10', 'A', 'a:b=2:3=8:12 (multiply by 4), b:c=4:5=12:15 (multiply by 3). So a:b:c=8:12:15.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 2, 'GS', 'Math & Reasoning', 4, 'A boat goes 24 km downstream in 2 hours. The speed of the boat downstream is:', '10 km/h', '12 km/h', '14 km/h', '16 km/h', 'B', 'Speed = distance/time = 24/2 = 12 km/h.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 2, 'GS', 'Math & Reasoning', 5, 'Find the odd one out: 4, 9, 16, 26, 36', '9', '16', '26', '36', 'C', '4,9,16,25,36 are perfect squares; 26 breaks the pattern (should be 25).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 2, 'GS', 'Science (Physics/Chem/Bio)', 6, 'The SI unit of force is:', 'Joule', 'Newton', 'Watt', 'Pascal', 'B', 'Newton (N) is the SI unit of force, defined as kg.m/s2.', 'E');
