INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Fundamentals', 2, '1 Kilobyte (KB) equals:', '1000 bytes', '1024 bytes', '100 bytes', '1024 bits', 'B', 'In binary terms, 1 KB = 2^10 bytes = 1024 bytes.', 'E');
