INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Fundamentals', 5, 'Which of the following is an output device?', 'Keyboard', 'Mouse', 'Monitor', 'Scanner', 'C', 'A Monitor displays output; keyboard, mouse and scanner are input devices.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Fundamentals', 6, 'The full form of URL is:', 'Universal Resource Locator', 'Uniform Resource Locator', 'Uniform Retrieval Locator', 'Universal Retrieval Link', 'B', 'URL = Uniform Resource Locator, the address of a resource on the web.', 'E');
