INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Fundamentals', 8, 'Which of these is volatile memory?', 'ROM', 'Cache (RAM-based)', 'Hard Disk', 'SSD', 'B', 'Cache memory, being RAM-based, is volatile and loses data when powered off.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'System Software', 9, 'Which is an example of application software?', 'Windows OS', 'Device Driver', 'MS Excel', 'Linux Kernel', 'C', 'MS Excel is application software used for spreadsheets; the others are system software.', 'E');
