INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'System Software', 12, 'Which is an example of proprietary (closed-source) operating system?', 'Linux', 'Windows', 'Android (AOSP)', 'Ubuntu', 'B', 'Microsoft Windows is proprietary/closed-source software.', 'E');
