INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 14, 'The time complexity of inserting an element at the beginning of an array of size n is:', 'O(1)', 'O(n)', 'O(log n)', 'O(n^2)', 'B', 'Inserting at the beginning requires shifting all n elements, giving O(n).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 15, 'Which data structure is used to implement a priority queue efficiently?', 'Array only', 'Linked List only', 'Heap', 'Stack', 'C', 'A Heap (min-heap or max-heap) is the standard efficient structure for priority queues.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 16, 'Merge Sort uses which algorithmic technique?', 'Greedy', 'Divide and Conquer', 'Dynamic Programming', 'Backtracking', 'B', 'Merge Sort divides the array into halves, sorts them, and merges - a Divide and Conquer approach.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 17, 'In a doubly linked list, each node contains:', 'Only data', 'Data and one pointer', 'Data and two pointers (next and previous)', 'Only pointers', 'C', 'A doubly linked list node has data plus pointers to both next and previous nodes.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 18, 'Which traversal visits Root-Left-Right in a binary tree?', 'Inorder', 'Preorder', 'Postorder', 'Level order', 'B', 'Preorder traversal visits the Root first, then Left subtree, then Right subtree.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 19, 'The maximum number of nodes at level ''l'' of a binary tree is:', 'l', '2l', '2^l', '2^(l-1)', 'C', 'At level l (root at level 0), maximum nodes = 2^l.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Data Structures', 20, 'Which sorting algorithm is ''in-place'' and has O(1) extra space?', 'Merge Sort', 'Bubble Sort', 'Counting Sort', 'Radix Sort', 'B', 'Bubble Sort sorts in-place using only a constant amount of extra memory.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 21, 'Which of these is a valid C variable name?', '2value', '_value', 'value-2', 'value 2', 'B', 'Variable names can start with an underscore; they cannot start with a digit or contain spaces/hyphens.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 22, 'What is the output of: printf("%d", 10%3);', '3', '1', '0', '10', 'B', 'The modulus operator gives the remainder: 10 divided by 3 leaves remainder 1.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 23, 'Which keyword is used to exit a loop prematurely in C?', 'exit', 'stop', 'break', 'return', 'C', 'The ''break'' statement immediately terminates the nearest enclosing loop.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 24, 'Which keyword skips the current iteration and moves to the next in a loop?', 'break', 'continue', 'skip', 'next', 'B', '''continue'' skips the rest of the current iteration and proceeds to the next.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 25, 'The ''#include'' directive in C is used to:', 'Declare a function', 'Include a header file', 'Define a macro', 'Comment code', 'B', '''#include'' is a preprocessor directive to include the contents of header files.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 26, 'Which operator has the highest precedence in C?', 'Assignment (=)', 'Parentheses ()', 'Addition (+)', 'Logical AND (&&)', 'B', 'Parentheses have the highest precedence, forcing evaluation of the enclosed expression first.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 27, 'In C, an array index starts from:', '1', '0', '-1', 'Depends on declaration', 'B', 'C arrays are zero-indexed; the first element is at index 0.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 28, 'What does the ''free()'' function do in C?', 'Allocates memory', 'Deallocates dynamically allocated memory', 'Declares a variable', 'Deletes a file', 'B', 'free() releases memory previously allocated by malloc(), calloc(), or realloc().', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 29, 'Which of these correctly represents a function prototype in C?', 'int add(int, int);', 'int add(int, int){}', 'function add(int,int);', 'int add[int,int];', 'A', 'A function prototype declares the return type, name, and parameter types, ending with a semicolon.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C Programming', 30, 'What is the result of: 5 == 5.0 in C?', '0 (false)', '1 (true)', 'Compilation error', 'Undefined', 'B', 'C performs implicit type conversion; 5 is promoted to 5.0 for comparison, yielding true (1).', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 31, 'Which OOP concept means ''many forms''?', 'Encapsulation', 'Inheritance', 'Polymorphism', 'Abstraction', 'C', 'Polymorphism (Greek: ''many forms'') allows a function/object to behave differently in different contexts.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 32, 'Which type of inheritance forms a chain: A -> B -> C?', 'Single', 'Multiple', 'Multilevel', 'Hierarchical', 'C', 'Multilevel inheritance involves a chain where a class inherits from a class that itself inherits from another.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 33, 'A class that cannot be instantiated directly (has at least one pure virtual function) is called:', 'Concrete class', 'Abstract class', 'Friend class', 'Static class', 'B', 'An Abstract class contains at least one pure virtual function and cannot be instantiated.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 34, 'Which type of polymorphism is achieved via function overloading?', 'Runtime polymorphism', 'Compile-time polymorphism', 'Dynamic polymorphism', 'No polymorphism', 'B', 'Function overloading is resolved at compile time, hence called compile-time (static) polymorphism.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 35, 'A ''friend'' function in C++ can access:', 'Only public members', 'Private and protected members of a class', 'Only static members', 'Nothing', 'B', 'A friend function, though not a member, is granted access to a class''s private and protected members.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 36, 'Which C++ concept hides internal implementation details and shows only functionality?', 'Encapsulation', 'Abstraction', 'Inheritance', 'Overloading', 'B', 'Abstraction focuses on hiding implementation complexity and exposing only essential features.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 37, 'In C++, a constructor with the same name as the class and no return type used to copy an object is called:', 'Default constructor', 'Parameterized constructor', 'Copy constructor', 'Destructor', 'C', 'A copy constructor initializes a new object as a copy of an existing object of the same class.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'C++ & OOP', 38, 'Which C++ operator is used to dynamically allocate memory (in place of C''s malloc)?', 'alloc', 'new', 'create', 'malloc', 'B', 'The ''new'' operator allocates memory dynamically on the heap in C++.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 39, 'Which SQL command adds a new column to an existing table?', 'ALTER TABLE ... ADD COLUMN', 'UPDATE TABLE', 'INSERT COLUMN', 'CREATE COLUMN', 'A', 'ALTER TABLE ... ADD COLUMN modifies the table structure by adding a new column.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 40, 'Which key can accept NULL values but must be unique when not null?', 'Primary Key', 'Foreign Key', 'Unique Key', 'Composite Key', 'C', 'A Unique key allows one NULL value while enforcing uniqueness on non-null entries.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 41, 'In BCNF (Boyce-Codd Normal Form), every determinant must be a:', 'Foreign key', 'Candidate key', 'Composite key', 'Primary key only', 'B', 'BCNF requires that for every functional dependency X->Y, X must be a candidate key.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 42, 'Which SQL aggregate function returns the number of rows?', 'SUM()', 'AVG()', 'COUNT()', 'MAX()', 'C', 'COUNT() returns the number of rows matching a specified criterion.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 43, 'A view in SQL is:', 'A physical table', 'A virtual table based on a query result', 'An index', 'A stored procedure', 'B', 'A view is a virtual table whose content is defined by a stored SQL query.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 44, 'Which SQL clause is used to sort query results?', 'GROUP BY', 'ORDER BY', 'SORT BY', 'ARRANGE BY', 'B', 'ORDER BY sorts the result set by one or more columns.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 45, 'The property of a transaction ensuring it survives system failure once committed:', 'Atomicity', 'Consistency', 'Isolation', 'Durability', 'D', 'Durability guarantees that once a transaction is committed, it remains so even after a crash.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 46, 'Which type of JOIN returns all rows from the left table and matched rows from the right?', 'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'FULL JOIN', 'B', 'LEFT JOIN returns all rows from the left table, with NULLs for unmatched right rows.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 47, 'Which is a Data Definition Language (DDL) command?', 'SELECT', 'UPDATE', 'CREATE', 'INSERT', 'C', 'CREATE (along with ALTER, DROP) is a DDL command used to define database structures.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 48, 'Which is a Data Manipulation Language (DML) command?', 'CREATE', 'DROP', 'UPDATE', 'ALTER', 'C', 'UPDATE (along with SELECT, INSERT, DELETE) is a DML command used to manipulate data.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 49, 'A composite key is formed by:', 'A single unique attribute', 'Combining two or more attributes to uniquely identify a row', 'A foreign key alone', 'Any attribute', 'B', 'A composite key uses two or more columns together to ensure uniqueness.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'DBMS & SQL', 50, 'Which term describes redundant data storage leading to anomalies?', 'Normalization', 'Denormalization issue / Data redundancy', 'Indexing', 'Partitioning', 'B', 'Data redundancy (unnormalized data) causes insertion, update, and deletion anomalies.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 51, 'Which OSI layer is responsible for routing packets between networks?', 'Data Link Layer', 'Network Layer', 'Transport Layer', 'Session Layer', 'B', 'The Network Layer (Layer 3) handles logical addressing and routing across networks.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 52, 'Which protocol is used to transfer files between computers over a network?', 'HTTP', 'FTP', 'SMTP', 'DNS', 'B', 'FTP (File Transfer Protocol) is specifically designed for transferring files.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 53, 'A network confined to a single building or campus is called:', 'WAN', 'MAN', 'LAN', 'GAN', 'C', 'LAN (Local Area Network) typically covers a small area like a building or campus.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 54, 'Which device regenerates and amplifies signals over long distances?', 'Switch', 'Repeater', 'Bridge', 'Gateway', 'B', 'A Repeater boosts/regenerates weakened signals to extend transmission distance.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 55, 'What does ''Wi-Fi'' primarily use for wireless communication?', 'Infrared', 'Radio waves', 'Bluetooth waves', 'Microwaves only', 'B', 'Wi-Fi (IEEE 802.11) uses radio waves for wireless local area networking.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 56, 'Which protocol resolves domain names to IP addresses?', 'DHCP', 'DNS', 'ARP', 'SNMP', 'B', 'DNS (Domain Name System) translates human-readable domain names into IP addresses.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 57, 'A network topology where all devices connect to a single central cable is called:', 'Star', 'Ring', 'Bus', 'Mesh', 'C', 'In Bus topology, all devices share a single central communication cable.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 58, 'Which is a private IP address range (Class C)?', '10.0.0.0-10.255.255.255', '172.16.0.0-172.31.255.255', '192.168.0.0-192.168.255.255', '8.8.8.0-8.8.8.255', 'C', '192.168.0.0 - 192.168.255.255 is the reserved private Class C IP address range.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 59, 'Which security mechanism verifies a user''s identity before granting access?', 'Encryption', 'Authentication', 'Compression', 'Firewall', 'B', 'Authentication is the process of verifying the identity of a user or system.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Networks', 60, 'Which attack involves intercepting communication between two parties without their knowledge?', 'Phishing', 'Man-in-the-Middle attack', 'Brute force attack', 'Keylogging', 'B', 'A Man-in-the-Middle (MITM) attack secretly intercepts and possibly alters communication between two parties.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 61, 'Which unit directs and coordinates operations of the computer?', 'ALU', 'Control Unit', 'Memory Unit', 'I/O Unit', 'B', 'The Control Unit directs the operation of the processor and coordinates all other components.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 62, 'Clock speed of a CPU is measured in:', 'Bytes', 'Hertz (Hz)', 'Bits', 'Watts', 'B', 'CPU clock speed is measured in Hertz (commonly GHz).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 63, 'Which type of memory retains data even after the power is switched off?', 'RAM', 'Cache', 'ROM', 'Registers', 'C', 'ROM (Read-Only Memory) is non-volatile and retains data without power.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 64, 'In the instruction cycle, the step that determines the operation to perform is:', 'Fetch', 'Decode', 'Execute', 'Store', 'B', 'The Decode stage interprets the fetched instruction to determine the required operation.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 65, 'Which addressing mode specifies the operand''s memory address indirectly through a register?', 'Immediate addressing', 'Direct addressing', 'Register indirect addressing', 'Implied addressing', 'C', 'In register indirect addressing, the register holds the address of the operand.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 66, 'CISC architecture is characterized by:', 'Few simple instructions', 'A large set of complex instructions', 'No microcode', 'Only used in embedded systems', 'B', 'CISC uses a large set of complex, multi-cycle instructions.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 67, 'Secondary memory is also known as:', 'Primary memory', 'Auxiliary/external memory', 'Cache memory', 'Register memory', 'B', 'Secondary memory (like hard disks) is also called auxiliary or external memory.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Computer Architecture', 68, 'Which bus carries data between the CPU, memory, and I/O devices?', 'Address bus', 'Data bus', 'Control bus', 'System clock', 'B', 'The Data bus carries the actual data being transferred between components.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 69, 'Convert binary 11111 to decimal:', '29', '30', '31', '32', 'C', '1x16+1x8+1x4+1x2+1x1 = 31.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 70, 'Convert decimal 50 to binary:', '110010', '110001', '111010', '101010', 'A', '50 = 32+16+2 = 110010 in binary.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 71, 'In Boolean algebra, A + 1 equals:', '0', '1', 'A', 'A''', 'B', 'By the annulment law, A OR 1 is always 1, regardless of A''s value.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 72, 'In Boolean algebra, A . 0 equals:', '0', '1', 'A', 'A''', 'A', 'By the annulment law, A AND 0 is always 0, regardless of A''s value.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 73, 'The output of a NOR gate is 1 only when:', 'Both inputs are 1', 'Both inputs are 0', 'Inputs differ', 'At least one input is 1', 'B', 'NOR gate outputs 1 only when all inputs are 0.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 74, 'Which gate produces an output of 0 only when all inputs are 1?', 'AND', 'OR', 'NAND', 'NOR', 'C', 'NAND gate output is 0 only when every input is 1.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 75, 'Octal number system has a base of:', '4', '6', '8', '10', 'C', 'The Octal number system uses 8 digits (0-7), hence base 8.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 76, 'Convert hexadecimal 2A to decimal:', '40', '42', '44', '46', 'B', '2A: 2x16 + 10x1 = 32+10 = 42.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 77, 'De Morgan''s theorem states that (A+B)'' equals:', 'A'' + B''', 'A'' . B''', 'A + B', 'A . B', 'B', 'De Morgan''s law: (A+B)'' = A''.B''.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Number Systems & Boolean Algebra', 78, '2''s complement of binary 0110 is:', '1001', '1010', '1000', '0111', 'B', '1''s complement of 0110 is 1001; adding 1 gives 2''s complement: 1010.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Cyber Security', 79, 'Software designed to self-replicate and spread across networks without user action is called:', 'Trojan Horse', 'Worm', 'Spyware', 'Ransomware', 'B', 'A Worm is a standalone malware that replicates itself to spread across networks, unlike a Trojan.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (3, 3, 'CS', 'Cyber Security', 80, 'Malicious software that encrypts a victim''s files and demands payment for the decryption key is called:', 'Adware', 'Spyware', 'Ransomware', 'Rootkit', 'C', 'Ransomware encrypts victim data and demands a ransom payment for restoring access.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 1, 'Choose the correct form: They ___ playing football since morning.', 'is', 'are', 'was', 'have been', 'D', 'Present perfect continuous for an action starting in the past and continuing now: ''have been'' + verb-ing.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 2, 'Select the correctly spelt word:', 'Necesary', 'Necessary', 'Neccessary', 'Necessery', 'B', 'Necessary is the correct spelling (one ''c'', double ''s'').', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 3, 'Fill in the blank: She is married ___ a doctor.', 'with', 'to', 'by', 'for', 'B', '''Married to'' is the correct fixed preposition in English.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 4, 'Synonym of ''Abundant'':', 'Scarce', 'Plentiful', 'Rare', 'Limited', 'B', 'Abundant means existing in large quantities; plentiful.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 5, 'Antonym of ''Optimistic'':', 'Hopeful', 'Pessimistic', 'Cheerful', 'Positive', 'B', 'Optimistic (hopeful) is opposite of Pessimistic (expecting the worst).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 6, 'Change to indirect speech: She said, "I will help you tomorrow."', 'She said that she would help me the next day.', 'She said that she will help me tomorrow.', 'She said she helped me tomorrow.', 'She says she will help me tomorrow.', 'A', 'Future tense ''will'' shifts to ''would'', and ''tomorrow'' shifts to ''the next day'' in reported speech.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 7, 'The idiom ''Burning the midnight oil'' means:', 'Wasting money', 'Working late into the night', 'Starting a fire', 'Being careless', 'B', 'It means working or studying late into the night.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 8, 'Identify the correctly punctuated sentence:', 'Lets go, she said.', '"Let''s go," she said.', 'Lets go she said', '"Lets go" she said.', 'B', 'Direct speech requires quotation marks and the apostrophe in the contraction ''Let''s''.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 9, 'Choose the correct superlative form: This is the ___ movie I have ever seen.', 'good', 'better', 'best', 'goodest', 'C', '''Good'' has irregular comparison: good - better - best.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'English', 'English Grammar & Vocabulary', 10, 'The phrase ''To let the cat out of the bag'' means:', 'To free an animal', 'To reveal a secret accidentally', 'To start a fight', 'To hide something', 'B', 'It means to accidentally reveal a secret or hidden information.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 11, '''पवन'' शब्द किस प्रकार की संज्ञा है?', 'जातिवाचक', 'व्यक्तिवाचक', 'भाववाचक', 'द्रव्यवाचक', 'A', 'पवन (हवा) एक सामान्य वस्तु का वाचक है, अतः जातिवाचक संज्ञा है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 12, '''आदि'' शब्द का विलोम है:', 'प्रारंभ', 'अंत', 'मध्य', 'पूर्ण', 'B', 'आदि (शुरुआत) का विलोम अंत है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 13, '''गबन'' उपन्यास के लेखक कौन हैं?', 'प्रेमचंद', 'जयशंकर प्रसाद', 'भारतेंदु हरिश्चंद्र', 'महादेवी वर्मा', 'A', 'गबन प्रेमचंद का प्रसिद्ध सामाजिक उपन्यास है।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 14, '''निडर'' शब्द में उपसर्ग है:', 'निः', 'निड़र', 'डर', 'निर्', 'A', 'निः + डर = निडर, जिसमें ''निः'' उपसर्ग है।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 15, '''आँखों में धूल झोंकना'' मुहावरे का अर्थ है:', 'साफ करना', 'धोखा देना', 'पढ़ना', 'देखना', 'B', 'इसका अर्थ है किसी को धोखा देना या छल करना।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 16, 'निम्न में तद्भव शब्द कौन-सा है?', 'कर्म', 'काम', 'धर्म', 'मूल्य', 'B', 'काम, संस्कृत के ''कर्म'' शब्द का तद्भव रूप है।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 17, '''जो सब कुछ जानता हो'' के लिए एक शब्द है:', 'बुद्धिमान', 'सर्वज्ञ', 'विद्वान', 'ज्ञानी', 'B', 'सर्वज्ञ = जो सब कुछ जानता हो।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 18, 'हिंदी में मात्राओं की संख्या कितनी होती है?', '10', '11', '12', '13', 'C', 'हिंदी में सामान्यतः 12 मात्राएँ (स्वरों की मात्राएँ) मानी जाती हैं।', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 19, '''पक्षी आकाश में उड़ता है'' वाक्य में क्रिया का भेद है:', 'सकर्मक', 'अकर्मक', 'द्विकर्मक', 'प्रेरणार्थक', 'B', '''उड़ना'' में कर्म नहीं है, अतः यह अकर्मक क्रिया है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 20, 'संधि विच्छेद करें: ''महोत्सव''', 'महा + उत्सव', 'मह + उत्सव', 'महो + त्सव', 'महा + ओत्सव', 'A', 'महा + उत्सव में गुण संधि से ''महोत्सव'' बनता है।', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 21, '''आरंभ'' का विलोम शब्द है:', 'शुरुआत', 'अंत', 'मध्य', 'प्रारंभ', 'B', 'आरंभ (शुरुआत) का विलोम अंत है।', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 1, 'Hindi', 'Hindi Grammar & Vyakaran', 22, 'कारक चिह्न ''से'' किस कारक में प्रयुक्त होता है?', 'कर्ता कारक', 'कर्म कारक', 'करण/अपादान कारक', 'संबंध कारक', 'C', '''से'' विभक्ति चिह्न करण या अपादान कारक में प्रयुक्त होता है।', 'M');
