INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'System Software', 12, 'Device drivers are a type of:', 'Application software', 'System software', 'Utility only', 'Firmware only', 'B', 'Device drivers are system software that allow the OS to communicate with hardware devices.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 13, 'Which data structure is ideal for implementing ''Undo'' functionality in software?', 'Queue', 'Stack', 'Array', 'Tree', 'B', 'A Stack (LIFO) naturally supports undoing the most recent action first.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 14, 'The time complexity of accessing an element in an array by index is:', 'O(1)', 'O(n)', 'O(log n)', 'O(n^2)', 'A', 'Array elements are accessed directly via index calculation, giving constant time O(1).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 15, 'Which data structure is used for Breadth-First Search (BFS) traversal of a graph?', 'Stack', 'Queue', 'Heap', 'Array', 'B', 'BFS uses a Queue to process nodes level by level.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 16, 'Which data structure is used for Depth-First Search (DFS) traversal of a graph?', 'Queue', 'Stack (or recursion)', 'Heap', 'Linked List only', 'B', 'DFS uses a Stack (implicitly via recursion) to explore as deep as possible before backtracking.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 17, 'A complete binary tree with n nodes has a height of approximately:', 'n', 'n/2', 'log2(n)', 'n^2', 'C', 'A complete binary tree''s height grows logarithmically with the number of nodes: O(log n).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 18, 'Which sorting algorithm repeatedly selects the minimum element and places it at the beginning?', 'Bubble Sort', 'Selection Sort', 'Insertion Sort', 'Quick Sort', 'B', 'Selection Sort selects the smallest remaining element and moves it into sorted position each pass.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 19, 'In a hash table, when two keys map to the same index, it is called a:', 'Overflow', 'Underflow', 'Collision', 'Duplication', 'C', 'A hash collision occurs when two different keys hash to the same table index.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Data Structures', 20, 'Which data structure allows insertion and deletion from both ends?', 'Stack', 'Queue', 'Deque (Double-ended Queue)', 'Array', 'C', 'A Deque supports insertion and deletion from both the front and rear ends.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 21, 'Which of these is a correct way to declare a constant in C?', 'const int x = 5;', 'constant int x = 5;', 'int const x;', '#const x 5', 'A', '''const int x = 5;'' correctly declares a constant integer using the const keyword.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 22, 'What does ''sizeof(float)'' typically return on standard systems?', '2', '4', '8', '16', 'B', 'A float typically occupies 4 bytes on most systems.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 23, 'Which of these correctly declares a 2D array in C?', 'int arr[3][4];', 'int arr(3,4);', 'int arr[3,4];', 'array int[3][4];', 'A', '''int arr[3][4];'' is the correct syntax for declaring a 2D array in C.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 24, 'What is the purpose of the ''return'' statement in a function?', 'To exit the program', 'To return a value and exit the function', 'To declare a variable', 'To print output', 'B', '''return'' sends a value back to the caller and terminates the function''s execution.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 25, 'Which operator is used for pointer dereferencing in C?', '&', '*', '->', '%', 'B', 'The ''*'' operator, when applied to a pointer, dereferences it to access the value it points to.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 26, 'What is a ''recursive function''?', 'A function with no parameters', 'A function that calls itself', 'A function that returns void', 'A function defined twice', 'B', 'A recursive function is one that calls itself to solve smaller instances of a problem.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 27, 'Which of these is NOT a valid C data type?', 'int', 'float', 'string', 'char', 'C', '''string'' is not a built-in C data type; C uses character arrays for strings.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 28, 'What does the ''typedef'' keyword do in C?', 'Defines a new function', 'Creates an alias for an existing data type', 'Declares a global variable', 'Deletes a data type', 'B', '''typedef'' creates a new name (alias) for an existing data type.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 29, 'Which format specifier is used to print a floating point number in C?', '%d', '%c', '%f', '%s', 'C', '''%f'' is the format specifier for printing float/double values in printf().', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C Programming', 30, 'What is the output of: int x=5; x += 3; printf("%d", x);', '5', '3', '8', '53', 'C', '''x += 3'' means x = x + 3 = 5+3 = 8.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 31, 'Which of the following best defines an ''object'' in OOP?', 'A class blueprint', 'An instance of a class', 'A function', 'A data type', 'B', 'An object is a concrete instance created from a class blueprint/template.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 32, 'Which type of inheritance allows one base class and multiple derived classes?', 'Single', 'Multiple', 'Hierarchical', 'Multilevel', 'C', 'In Hierarchical inheritance, multiple derived classes inherit from a single base class.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 33, 'In C++, which access specifier allows access only within the same class and derived classes?', 'public', 'private', 'protected', 'friend', 'C', '''protected'' members are accessible within the class and by derived (child) classes.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 34, 'What is method/function overriding used for?', 'Reusing base class code exactly', 'Redefining a base class method''s behavior in a derived class', 'Creating multiple constructors', 'Hiding data members', 'B', 'Overriding allows a derived class to provide a specific implementation of a method already defined in its base class.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 35, 'Which C++ concept binds data and functions together into a single unit?', 'Inheritance', 'Class (Encapsulation)', 'Polymorphism', 'Abstraction', 'B', 'A Class encapsulates data members and member functions into a single unit.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 36, 'Static binding (compile-time) is associated with which polymorphism type?', 'Function overloading and operator overloading', 'Virtual functions', 'Dynamic dispatch', 'Runtime polymorphism', 'A', 'Function/operator overloading is resolved at compile time, hence static (early) binding.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 37, 'Which C++ keyword is used to delete a dynamically allocated object?', 'remove', 'delete', 'free', 'destroy', 'B', 'The ''delete'' operator deallocates memory that was allocated with ''new'' in C++.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'C++ & OOP', 38, 'A destructor in C++ is denoted by which symbol before the class name?', '#', '&', '~', '@', 'C', 'A destructor is written as ~ClassName(), using the tilde (~) symbol.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 39, 'In SQL, which statement is used to remove a table entirely, including its structure?', 'DELETE', 'TRUNCATE', 'DROP', 'REMOVE', 'C', 'DROP TABLE removes the entire table along with its structure and data.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 40, 'Which normal form deals with multi-valued dependencies?', '2NF', '3NF', 'BCNF', '4NF', 'D', 'Fourth Normal Form (4NF) addresses and eliminates multi-valued dependencies.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 41, 'Which SQL clause combines rows from two or more tables based on a related column?', 'UNION', 'JOIN', 'GROUP BY', 'MERGE', 'B', 'JOIN combines rows from multiple tables based on a related column between them.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 42, 'Which term refers to the process of organizing data to minimize redundancy?', 'Indexing', 'Normalization', 'Replication', 'Partitioning', 'B', 'Normalization is the process of structuring a database to reduce data redundancy.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 43, 'Which SQL command is used to insert new rows into a table?', 'ADD', 'INSERT INTO', 'APPEND', 'CREATE', 'B', 'INSERT INTO is the standard SQL command to add new rows of data into a table.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 44, 'A ''trigger'' in a database is:', 'A stored procedure that runs automatically on a specified event', 'A type of index', 'A user privilege', 'A query optimizer', 'A', 'A trigger automatically executes a set of actions when a specified database event (like INSERT/UPDATE) occurs.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 45, 'Which SQL keyword is used to combine the result sets of two SELECT statements?', 'JOIN', 'UNION', 'MERGE', 'LINK', 'B', 'UNION combines the results of two or more SELECT queries into a single result set.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 46, 'In the ACID properties, ''Isolation'' ensures that:', 'Transactions are executed in isolation from each other, without interference', 'Data is permanently saved', 'The database structure doesn''t change', 'Only authorized users can access data', 'A', 'Isolation ensures concurrently executing transactions do not interfere with each other''s intermediate states.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 47, 'Which key in a table refers to the primary key of another table?', 'Candidate key', 'Foreign key', 'Alternate key', 'Super key', 'B', 'A Foreign key establishes a link by referencing the primary key of another table.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 48, 'What does DDL stand for in SQL?', 'Data Definition Language', 'Data Deletion Language', 'Database Design Language', 'Data Duplication Language', 'A', 'DDL = Data Definition Language, used to define database schema (CREATE, ALTER, DROP).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 49, 'Which SQL clause restricts the rows returned by a SELECT query based on a condition?', 'SELECT', 'FROM', 'WHERE', 'HAVING', 'C', 'The WHERE clause filters rows based on a specified condition before any grouping.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'DBMS & SQL', 50, 'A weak entity in an E-R diagram is one that:', 'Has its own primary key', 'Cannot be uniquely identified without a related strong entity', 'Has no attributes', 'Is always a relationship', 'B', 'A weak entity depends on a related (owner/strong) entity for its unique identification.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 51, 'Which layer of the OSI model deals with encryption and data formatting?', 'Transport Layer', 'Session Layer', 'Presentation Layer', 'Application Layer', 'C', 'The Presentation Layer handles data translation, encryption, and formatting.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 52, 'Which protocol is used to securely access a remote computer over a network?', 'Telnet', 'SSH', 'FTP', 'HTTP', 'B', 'SSH (Secure Shell) provides encrypted remote access, unlike the insecure Telnet.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 53, 'A network spanning a city is called:', 'LAN', 'MAN', 'WAN', 'PAN', 'B', 'MAN (Metropolitan Area Network) covers a city or a large campus area.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 54, 'Which device connects different networks and determines the best path for data?', 'Hub', 'Switch', 'Router', 'Repeater', 'C', 'A Router connects different networks and determines the optimal path for data packets.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 55, 'Bandwidth in networking is measured in:', 'Bytes', 'Bits per second (bps)', 'Hertz only', 'Meters', 'B', 'Bandwidth, the data transfer capacity, is measured in bits per second (bps, Mbps, Gbps).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 56, 'Which protocol is used to retrieve email from a mail server (downloading and deleting)?', 'SMTP', 'IMAP', 'POP3', 'HTTP', 'C', 'POP3 (Post Office Protocol) typically downloads and removes email from the server.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 57, 'A VPN (Virtual Private Network) is primarily used to:', 'Increase internet speed', 'Create a secure, encrypted connection over a public network', 'Block websites', 'Store data online', 'B', 'A VPN creates a secure encrypted tunnel for private communication over a public network.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 58, 'Which of these is an example of a Class A IP address?', '10.0.0.1', '172.16.0.1', '192.168.1.1', '224.0.0.1', 'A', 'Class A addresses range from 1.0.0.0 to 126.255.255.255; 10.0.0.1 falls in this range.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 59, 'SSL/TLS protocols are primarily used for:', 'Compressing files', 'Securing data transmission over networks', 'Increasing bandwidth', 'Assigning IP addresses', 'B', 'SSL/TLS provide encryption to secure data transmitted over networks (e.g., HTTPS).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Networks', 60, 'Which cyberattack tricks users into revealing confidential information via a fake website?', 'DDoS attack', 'Phishing', 'Spoofing', 'Brute force attack', 'B', 'Phishing uses fraudulent websites/messages to trick users into revealing sensitive data.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 61, 'Which component temporarily stores data and instructions currently being processed?', 'Hard Disk', 'RAM', 'ROM', 'Cache only', 'B', 'RAM (Random Access Memory) holds data/instructions actively being used by the CPU.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 62, 'Which of these best describes ''multiprocessing''?', 'Running one program on one CPU', 'Using two or more CPUs within a single computer system', 'Running multiple computers separately', 'Using one CPU for multiple unrelated tasks sequentially', 'B', 'Multiprocessing involves using multiple CPUs/processors within a single system to execute processes concurrently.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 63, 'In addressing modes, when the instruction contains the operand''s address directly, it''s called:', 'Immediate addressing', 'Direct addressing', 'Indirect addressing', 'Indexed addressing', 'B', 'In Direct addressing, the instruction directly specifies the memory address of the operand.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 64, 'Which memory type uses capacitors to store each bit and requires periodic refreshing?', 'SRAM', 'DRAM', 'ROM', 'Cache', 'B', 'DRAM (Dynamic RAM) stores bits using capacitors, which lose charge and need periodic refreshing.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 65, 'Interrupt handling allows a CPU to:', 'Ignore all incoming signals', 'Pause its current task to service an urgent request', 'Shut down safely', 'Increase its clock speed', 'B', 'Interrupts allow a CPU to temporarily pause its current task and respond to urgent events.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 66, 'Which unit converts a high-level instruction into micro-operations in some CPUs?', 'ALU', 'Control Unit (with microprogramming)', 'Cache Controller', 'Bus Controller', 'B', 'In microprogrammed control units, complex instructions are broken down into sequences of micro-operations.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 67, 'A ''word'' in computer architecture refers to:', 'A single character', 'The natural unit of data used by a CPU''s architecture', 'Only 8 bits', 'Only 32 bits always', 'B', 'A ''word'' is the standard number of bits a processor handles as a unit (varies by architecture, e.g., 32-bit, 64-bit).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Computer Architecture', 68, 'Which of these is the correct order from fastest to slowest in the memory hierarchy?', 'Cache, Registers, RAM, Hard Disk', 'Registers, Cache, RAM, Hard Disk', 'RAM, Cache, Registers, Hard Disk', 'Hard Disk, RAM, Cache, Registers', 'B', 'The memory hierarchy from fastest to slowest is: Registers > Cache > RAM > Hard Disk.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 69, 'Convert binary 10000 to decimal:', '14', '15', '16', '17', 'C', '1x16+0x8+0x4+0x2+0x1 = 16.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 70, 'Convert decimal 100 to binary:', '1100100', '1101000', '1110100', '1100010', 'A', '100 = 64+32+4 = 1100100 in binary.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 71, 'In Boolean algebra, (A'')'' equals:', '0', '1', 'A', 'A''', 'C', 'Double complement (Involution law): (A'')'' = A.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 72, 'A + AB simplifies to:', 'A', 'B', 'AB', 'A+B', 'A', 'By the absorption law, A + AB = A.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 73, '(A+B)(A+C) simplifies to:', 'A + BC', 'AB + C', 'A + B + C', 'ABC', 'A', 'By the distributive law, (A+B)(A+C) = A + BC.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 74, 'Which gate is also called the ''inverter''?', 'AND', 'OR', 'NOT', 'XOR', 'C', 'The NOT gate inverts the input (0 becomes 1, and 1 becomes 0), hence called the inverter.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 75, 'Binary Coded Decimal (BCD) uses how many bits to represent one decimal digit?', '2', '4', '8', '16', 'B', 'BCD represents each decimal digit (0-9) using a 4-bit binary code.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 76, 'Convert hexadecimal 1F to decimal:', '29', '30', '31', '32', 'C', '1F: 1x16 + 15x1 (F=15) = 16+15 = 31.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 77, 'De Morgan''s second theorem, (A.B)'' = A'' + B'', can be verified using:', 'Truth table', 'Karnaugh map only', 'Boolean simplification only', 'Cannot be verified', 'A', 'Truth tables can be constructed to verify De Morgan''s theorems by comparing both sides for all input combinations.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Number Systems & Boolean Algebra', 78, '1''s complement of binary 11001100 is:', '00110011', '11001100', '00111100', '11000011', 'A', '1''s complement flips every bit: 11001100 -> 00110011.', 'E');
