INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (4, 3, 'CS', 'Cyber Security', 80, 'Which security measure verifies a user with two different factors (e.g., password + OTP)?', 'Firewall', 'Two-Factor Authentication (2FA)', 'Antivirus', 'Encryption', 'B', 'Two-Factor Authentication (2FA) requires two distinct verification methods for enhanced security.', 'E');
