INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Data Structures', 18, 'What is the space complexity of Merge Sort?', 'O(1)', 'O(log n)', 'O(n)', 'O(n^2)', 'C', 'Merge Sort requires additional O(n) space for the temporary arrays used during merging.', 'M');
