INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Data Structures', 20, 'Dijkstra''s algorithm is used to find:', 'The minimum spanning tree', 'The shortest path in a weighted graph', 'A cycle in a graph', 'Topological order', 'B', 'Dijkstra''s algorithm finds the shortest path from a source node to all other nodes in a weighted graph.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 21, 'Which of these correctly initializes an array in C?', 'int arr[5] = {1,2,3,4,5};', 'int arr[5] = (1,2,3,4,5);', 'int arr(5) = {1,2,3,4,5};', 'array arr[5] = {1,2,3,4,5};', 'A', '''int arr[5] = {1,2,3,4,5};'' is the correct syntax for array initialization in C.', 'E');
