INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 23, 'Which of these is a logical operator in C?', '+', '&&', '=', '%', 'B', '''&&'' (logical AND) is a logical operator; the others are arithmetic/assignment operators.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 24, 'What does the ternary operator ''?:'' do in C?', 'Performs a loop', 'Provides a shorthand for if-else', 'Declares a function', 'Allocates memory', 'B', 'The ternary operator ''condition ? expr1 : expr2'' is a shorthand for a simple if-else statement.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 25, 'Which storage class in C makes a variable''s scope limited to the file it''s declared in?', 'auto', 'extern', 'static', 'register', 'C', 'A ''static'' global variable has file scope, limiting its visibility to that source file.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 26, 'What is a ''NULL pointer'' in C?', 'A pointer with garbage value', 'A pointer pointing to address 0, indicating it points to nothing', 'A pointer to an integer', 'An uninitialized variable', 'B', 'A NULL pointer is a special pointer value indicating it does not point to any valid memory location.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 27, 'Which function is used to read a string from user input in C?', 'scanf()', 'gets() or fgets()', 'getchar() only', 'readstring()', 'B', 'gets() (unsafe, deprecated) or fgets() (safer) are used to read a full line of string input in C.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 28, 'What is the result of integer overflow in C for a typical signed int?', 'A compile error', 'Undefined behavior (often wraps around)', 'Automatic conversion to float', 'Program termination always', 'B', 'Signed integer overflow in C is technically undefined behavior, though it commonly wraps around in practice.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 29, 'Which of these correctly represents a comment in C?', '// this is a comment', '** this is a comment **', '# this is a comment', ''' this is a comment', 'A', '''//'' starts a single-line comment in C (C99 onwards); ''/* */'' is used for multi-line comments.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C Programming', 30, 'What does the ''void'' keyword indicate for a function''s return type?', 'It returns an integer', 'It returns nothing', 'It returns a pointer', 'It causes an error', 'B', 'A function with return type ''void'' does not return any value.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 31, 'Which principle of OOP focuses on exposing only necessary details to the user?', 'Inheritance', 'Abstraction', 'Polymorphism', 'Overloading', 'B', 'Abstraction hides complex implementation and shows only essential features to the user.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 32, 'In C++, which keyword is used to define a class?', 'struct only', 'class', 'object', 'define', 'B', 'The ''class'' keyword is used to define a class in C++.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 33, 'Which of these is an example of ''has-a'' relationship (composition) in OOP?', 'A Car class inheriting from a Vehicle class', 'A Car class containing an Engine object', 'A function overloading another', 'A class implementing an interface', 'B', 'Composition (''has-a'') means one class contains an object of another class as a member, unlike inheritance (''is-a'').', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 34, 'What is ''operator overloading'' in C++?', 'Redefining the behavior of an operator for user-defined types', 'Using multiple operators together', 'Overloading a function', 'Creating new operators', 'A', 'Operator overloading allows existing operators (like +, -, ==) to work with user-defined class types.', 'M');
