INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 36, 'A ''virtual destructor'' in C++ is important when:', 'Using simple structs', 'Deleting a derived class object through a base class pointer', 'Never needed', 'Only for static classes', 'B', 'A virtual destructor ensures the correct (derived class) destructor is called when deleting via a base class pointer, preventing memory leaks.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 37, 'Which C++ standard library provides ready-made data structures like vectors and lists?', 'iostream', 'STL (Standard Template Library)', 'cmath', 'fstream', 'B', 'The STL (Standard Template Library) provides containers like vector, list, map, along with algorithms.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'C++ & OOP', 38, 'What does ''namespace std'' refer to in C++ programs?', 'A user-defined namespace', 'The standard namespace containing standard library components', 'A deprecated feature', 'A type of class', 'B', '''std'' is the standard namespace containing C++ standard library entities like cout, cin, vector, etc.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 39, 'Which SQL command is used to give a table or column a temporary alternative name?', 'RENAME', 'AS (alias)', 'ALTER', 'LABEL', 'B', 'The ''AS'' keyword creates an alias, a temporary name for a table or column in a query.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 40, 'In DBMS, ''concurrency control'' primarily deals with:', 'Backup and recovery', 'Managing simultaneous access to data by multiple users/transactions', 'Data encryption', 'Query optimization only', 'B', 'Concurrency control ensures correct results when multiple transactions execute simultaneously.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 41, 'Which SQL statement is used to modify existing data in a table?', 'SELECT', 'UPDATE', 'INSERT', 'CREATE', 'B', 'UPDATE is used to modify existing records in a database table.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 42, 'What is a ''stored procedure'' in SQL?', 'A saved SQL query stored in the database that can be reused', 'A type of index', 'A table constraint', 'A backup file', 'A', 'A stored procedure is a precompiled collection of SQL statements stored in the database for reuse.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 43, 'Which of these is an example of a many-to-many relationship in a database?', 'A student having one roll number', 'Students enrolled in multiple courses, and each course having multiple students', 'A person having one Aadhar number', 'An employee reporting to one manager', 'B', 'Students-Courses is a classic many-to-many relationship, often resolved using a junction/bridge table.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 44, 'Which SQL clause is used together with aggregate functions to group rows sharing a property?', 'ORDER BY', 'GROUP BY', 'WHERE', 'HAVING', 'B', 'GROUP BY groups rows that share values in specified columns, often used with aggregate functions.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 45, 'What is ''data integrity'' in the context of databases?', 'The speed of data retrieval', 'The accuracy, consistency, and reliability of data over its lifecycle', 'The size of the database', 'The number of users accessing data', 'B', 'Data integrity ensures data remains accurate, consistent, and reliable throughout its lifecycle.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 46, 'Which key ensures no two rows in a table can have the same combination of values for specified columns?', 'Foreign key', 'Unique/Candidate key', 'Index', 'Default constraint', 'B', 'A Unique key (or candidate key) enforces that no duplicate combinations exist for the specified columns.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 47, 'In SQL, the wildcard character ''%'' in a LIKE clause represents:', 'A single character', 'Zero or more characters', 'Exactly one digit', 'A NULL value', 'B', 'The ''%'' wildcard matches zero, one, or multiple characters in a LIKE pattern.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 48, 'Which term describes a database that stores data across multiple physical locations?', 'Centralized database', 'Distributed database', 'Relational database', 'Hierarchical database', 'B', 'A Distributed database stores data across multiple physical sites, often connected by a network.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 49, 'What does the SQL command ''COMMIT'' do?', 'Cancels a transaction', 'Permanently saves all changes made in the current transaction', 'Deletes a table', 'Creates a backup', 'B', 'COMMIT permanently saves all changes made during the current transaction to the database.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'DBMS & SQL', 50, 'Which of these best defines ''referential integrity''?', 'Ensuring foreign key values match a primary key value in the referenced table (or are NULL)', 'Ensuring passwords are encrypted', 'Ensuring tables have indexes', 'Ensuring queries run fast', 'A', 'Referential integrity ensures foreign key values correspond to existing primary key values in the related table.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 51, 'Which OSI layer is closest to the end user and handles application-level protocols like HTTP?', 'Presentation Layer', 'Session Layer', 'Application Layer', 'Transport Layer', 'C', 'The Application Layer (Layer 7) is the topmost OSI layer, handling protocols like HTTP, FTP, and SMTP directly used by applications.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 52, 'Which protocol is the foundation of data communication for the World Wide Web?', 'FTP', 'HTTP', 'SMTP', 'DNS', 'B', 'HTTP (HyperText Transfer Protocol) is the foundational protocol for transferring web pages.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 53, 'A network that spans across countries or continents is called:', 'LAN', 'MAN', 'WAN', 'PAN', 'C', 'WAN (Wide Area Network) spans large geographical areas, including countries and continents (e.g., the Internet).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 54, 'Which device operates at multiple OSI layers and can perform routing, switching, and firewall functions?', 'Hub', 'Repeater', 'Gateway/Multi-layer switch', 'Modem', 'C', 'A Gateway or multi-layer switch can operate across multiple OSI layers, combining routing and other functions.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 55, 'In networking, ''latency'' refers to:', 'The total data transfer capacity', 'The delay before data transfer begins following an instruction', 'The number of connected devices', 'The physical length of cable', 'B', 'Latency is the time delay between a request and the response/action, often measured in milliseconds.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 56, 'Which protocol version increased the IP address space to solve address exhaustion?', 'IPv3', 'IPv4', 'IPv5', 'IPv6', 'D', 'IPv6, with 128-bit addresses, was introduced to solve the address exhaustion problem of IPv4 (32-bit).', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 57, 'A ''proxy server'' primarily functions as:', 'A backup server', 'An intermediary between a client and the destination server', 'A type of virus', 'A database server', 'B', 'A proxy server acts as an intermediary, forwarding requests between clients and other servers.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 58, 'Which of these is a symmetric encryption algorithm?', 'RSA', 'AES', 'Diffie-Hellman', 'ECC', 'B', 'AES (Advanced Encryption Standard) is a symmetric encryption algorithm, using the same key for encryption and decryption.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 59, 'A ''zero-day'' vulnerability refers to:', 'A vulnerability discovered and patched immediately', 'A security flaw unknown to the vendor, exploited before a fix is available', 'A vulnerability that never causes harm', 'An outdated antivirus definition', 'B', 'A zero-day vulnerability is unknown to the software vendor, giving ''zero days'' to prepare a fix before it''s exploited.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Networks', 60, 'Which practice involves regularly changing passwords and using complex combinations to enhance security?', 'Social engineering', 'Password hygiene', 'Phishing', 'Spoofing', 'B', 'Good password hygiene (complexity, regular changes) helps reduce the risk of unauthorized access.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 61, 'Which unit is responsible for fetching, decoding, and executing instructions in sequence?', 'ALU', 'Control Unit', 'CPU (overall)', 'Memory Unit', 'C', 'The CPU as a whole manages the fetch-decode-execute cycle, coordinated by its Control Unit and ALU.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 62, 'Which memory access method allows any memory location to be accessed directly, regardless of position?', 'Sequential access', 'Random access', 'Serial access', 'Indexed access only', 'B', 'Random access memory allows any location to be accessed in roughly the same time, regardless of its position.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 63, 'A ''multi-core'' processor refers to a CPU that:', 'Has multiple independent processing units on a single chip', 'Runs at multiple clock speeds', 'Has multiple RAM slots', 'Uses multiple operating systems', 'A', 'A multi-core processor integrates two or more independent processing cores on a single chip for parallel processing.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 64, 'Which type of addressing mode uses no explicit address, with the operand being implied by the instruction itself?', 'Immediate addressing', 'Implied/Implicit addressing', 'Direct addressing', 'Indexed addressing', 'B', 'Implied (implicit) addressing means the operand location is inherently understood by the instruction (e.g., accumulator-based operations).', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 65, 'The term ''clock cycle'' refers to:', 'The physical size of the CPU', 'The basic unit of time in which a CPU performs one elementary operation', 'The number of cores in a CPU', 'The amount of cache memory', 'B', 'A clock cycle is the fundamental unit of time governing CPU operations, determined by the clock speed.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 66, 'Which type of computer architecture separates instruction and data memory/buses (unlike Von Neumann)?', 'CISC', 'RISC', 'Harvard Architecture', 'Pipeline Architecture', 'C', 'Harvard Architecture uses separate memory and buses for instructions and data, unlike the shared Von Neumann model.', 'H');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 67, 'What is the primary advantage of pipelining in a CPU?', 'Reduces power consumption significantly', 'Increases instruction throughput by overlapping execution stages', 'Increases memory capacity', 'Eliminates the need for cache', 'B', 'Pipelining overlaps the execution of multiple instructions at different stages, improving overall throughput.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Computer Architecture', 68, 'Which memory is directly addressable by the CPU without any translation?', 'Hard Disk', 'Main memory (RAM)', 'Cloud storage', 'Optical disk', 'B', 'Main memory (RAM) is directly addressable by the CPU, unlike secondary storage which requires I/O operations.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 69, 'Convert binary 101010 to decimal:', '40', '41', '42', '43', 'C', '1x32+0x16+1x8+0x4+1x2+0x1 = 32+8+2 = 42.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 70, 'Convert decimal 75 to binary:', '1001011', '1001010', '1000111', '1001101', 'A', '75 = 64+8+2+1 = 1001011 in binary.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 71, 'In Boolean algebra, the Distributive law states: A(B+C) = ?', 'A+B+C', 'AB+AC', 'A+BC', 'ABC', 'B', 'The Distributive law: A(B+C) = AB + AC, similar to arithmetic distribution.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 72, 'Which law states A+B = B+A in Boolean algebra?', 'Associative law', 'Commutative law', 'Distributive law', 'Identity law', 'B', 'The Commutative law states that the order of operands doesn''t affect the result of OR/AND operations.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 73, 'XNOR gate produces an output of 1 when:', 'Inputs differ', 'Inputs are the same (both 0 or both 1)', 'At least one input is 1', 'Always', 'B', 'XNOR (exclusive NOR) outputs 1 when both inputs are equal (either both 0 or both 1).', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 74, 'How many minterms are possible for a 3-variable Boolean function?', '4', '6', '8', '16', 'C', 'For n variables, there are 2^n minterms. For 3 variables: 2^3=8.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 75, 'Convert octal 25 to decimal:', '19', '20', '21', '23', 'C', '25 (octal): 2x8 + 5x1 = 16+5 = 21.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 76, 'Convert hexadecimal 3C to decimal:', '58', '59', '60', '61', 'C', '3C: 3x16 + 12x1 (C=12) = 48+12 = 60.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 77, 'A Karnaugh Map (K-map) is primarily used for:', 'Storing data', 'Simplifying Boolean expressions visually', 'Encrypting data', 'Measuring clock speed', 'B', 'A K-map is a graphical tool used to simplify Boolean algebra expressions by grouping adjacent minterms.', 'M');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Number Systems & Boolean Algebra', 78, '2''s complement of binary 1111 is:', '0000', '0001', '1110', '1000', 'B', '1''s complement of 1111 is 0000; adding 1 gives 2''s complement: 0001.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Cyber Security', 79, 'Which type of malware secretly monitors and collects a user''s activity, such as keystrokes?', 'Adware', 'Spyware', 'Worm', 'Rootkit', 'B', 'Spyware secretly monitors user activity and collects information without consent.', 'E');
INSERT INTO questions (set_number, part, section, topic, q_no, question, option_a, option_b, option_c, option_d, correct_option, explanation, difficulty) VALUES (5, 3, 'CS', 'Cyber Security', 80, 'A ''rootkit'' is malicious software primarily designed to:', 'Display unwanted ads', 'Gain and maintain hidden, privileged access to a system', 'Encrypt files for ransom', 'Send spam emails', 'B', 'A rootkit is designed to provide persistent, concealed, privileged (root/admin) access to an attacker while evading detection.', 'M');
